<?php
require_once __DIR__.'/includes/student_auth_check.php'; require_once __DIR__.'/config/db.php';
$tutorId=filter_input(INPUT_GET,'tutor_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]) ?: filter_input(INPUT_POST,'tutor_id',FILTER_VALIDATE_INT); $errors=[];$tutor=null;$subjects=[];$selectedDate=$_POST['booking_date']??date('Y-m-d');$selectedSlot=$_POST['slot']??'';
try{$pdo=db();$q=$pdo->prepare("SELECT t.id,t.hourly_rate,u.full_name FROM tutors t JOIN users u ON u.id=t.user_id WHERE t.id=:id AND u.is_verified=1");$q->execute(['id'=>$tutorId]);$tutor=$q->fetch();if($tutor){$q=$pdo->prepare('SELECT s.id,s.name FROM tutor_subjects ts JOIN subjects s ON s.id=ts.subject_id WHERE ts.tutor_id=:id GROUP BY s.id ORDER BY s.name');$q->execute(['id'=>$tutorId]);$subjects=$q->fetchAll();}}catch(Throwable $e){$errors[]='Unable to load tutor details.';}
if(!$tutor){http_response_code(404);exit('Tutor not found.');}
function slots_for(PDO $pdo,int $id,string $date):array{$day=['Sun'=>'Sun','Mon'=>'Mon','Tue'=>'Tue','Wed'=>'Wed','Thu'=>'Thu','Fri'=>'Fri','Sat'=>'Sat'][date('D',strtotime($date))];$q=$pdo->prepare("SELECT a.start_time,a.end_time FROM availability a WHERE a.tutor_id=:id AND ((a.is_recurring=1 AND a.day_of_week=:day) OR (a.is_recurring=0 AND a.specific_date=:date)) AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.tutor_id=a.tutor_id AND b.booking_date=:date AND b.start_time=a.start_time AND b.end_time=a.end_time AND b.status IN ('pending','accepted')) ORDER BY a.start_time");$q->execute(['id'=>$id,'day'=>$day,'date'=>$date]);return $q->fetchAll();}
$slots=slots_for($pdo,$tutorId,$selectedDate);
if($_SERVER['REQUEST_METHOD']==='POST'){$subjectId=filter_input(INPUT_POST,'subject_id',FILTER_VALIDATE_INT);$type=$_POST['session_type']??'';$address=trim((string)($_POST['address']??''));if(!verify_csrf($_POST['csrf_token']??null))$errors[]='Your session expired.';if(!in_array($type,['online','offline'],true))$errors[]='Select tuition type.';if($type==='offline'&&$address==='')$errors[]='Address is required for offline tuition.';if(!in_array($selectedSlot,array_map(fn($x)=>$x['start_time'].'|'.$x['end_time'],$slots),true))$errors[]='That time is no longer available.';if(!$subjectId)$errors[]='Select a subject.';if(!$errors)try{$pdo->beginTransaction();$slots=slots_for($pdo,$tutorId,$selectedDate);if(!in_array($selectedSlot,array_map(fn($x)=>$x['start_time'].'|'.$x['end_time'],$slots),true))throw new RuntimeException('That time was just booked.');[$start,$end]=explode('|',$selectedSlot);$q=$pdo->prepare("INSERT INTO bookings(student_id,tutor_id,subject_id,booking_date,start_time,end_time,session_type,address,status,price) VALUES(:student,:tutor,:subject,:date,:start,:end,:type,:address,'pending',:price)");$q->execute(['student'=>$_SESSION['user_id'],'tutor'=>$tutorId,'subject'=>$subjectId,'date'=>$selectedDate,'start'=>$start,'end'=>$end,'type'=>$type,'address'=>$address?:null,'price'=>$tutor['hourly_rate']]);$booking=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO notifications(user_id,type,message,related_id) SELECT user_id,'booking_pending',:message,:booking FROM tutors WHERE id=:tutor");$q->execute(['message'=>'A new booking request needs your response.','booking'=>$booking,'tutor'=>$tutorId]);$pdo->commit();header('Location: payment.php?booking_id='.$booking);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage()==='That time was just booked.'?$e->getMessage():'Unable to create booking. Please try again.';}}
$pageTitle='Book a session';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?>
<main class="section-soft py-5"><div class="container"><div class="booking-card mx-auto"><h1 class="h3">Book <?=e($tutor['full_name'])?></h1><p class="text-secondary">Choose a subject, date and available time.</p><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tutor_id" value="<?=$tutorId?>"><div class="mb-3"><label class="form-label">Subject</label><select class="form-select" name="subject_id" required><option value="">Select subject</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Date</label><input class="form-control" type="date" name="booking_date" min="<?=date('Y-m-d')?>" value="<?=e($selectedDate)?>" onchange="this.form.submit()"></div><div class="mb-3"><label class="form-label">Available time</label><select class="form-select" name="slot" required><option value="">Select a slot</option><?php foreach($slots as $slot):$value=$slot['start_time'].'|'.$slot['end_time'];?><option value="<?=e($value)?>" <?=$selectedSlot===$value?'selected':''?>><?=date('g:i A',strtotime($slot['start_time']))?> – <?=date('g:i A',strtotime($slot['end_time']))?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label d-block">Tuition type</label><input class="btn-check" type="radio" name="session_type" id="online" value="online" checked><label class="btn btn-outline-brand" for="online">Online</label><input class="btn-check" type="radio" name="session_type" id="offline" value="offline"><label class="btn btn-outline-brand" for="offline">Offline</label></div><div class="mb-3 d-none" id="addressGroup"><label class="form-label">Class address</label><textarea class="form-control" name="address"></textarea></div><div class="border rounded p-3 mb-4"><strong>Payment summary</strong><div class="d-flex justify-content-between mt-2"><span>Session fee</span><span>৳<?=number_format((float)$tutor['hourly_rate'])?></span></div></div><button class="btn btn-brand w-100">Book session</button></form></div></div></main><script>const a=document.querySelector('#addressGroup'),o=document.querySelector('#offline');function t(){a.classList.toggle('d-none',!o.checked);a.querySelector('textarea').required=o.checked}document.querySelectorAll('[name=session_type]').forEach(x=>x.onchange=t);t()</script><?php require __DIR__.'/includes/footer.php';?>
